package ph.edu.umak.momompurin

import ph.edu.umak.momompurin.data.QrEncoder

/**
 * A minimal QR DECODER, used only by the tests (UAT fix, item 9).
 *
 * ## Why a decoder exists in the test source set
 *
 * The payment QR is generated by hand-rolled code, so the risk is not "does it
 * compile" but "does a phone actually read it". Comparing the matrix to a
 * reference implementation catches a structural mistake, but it proves the two
 * agree rather than that the code is CORRECT - two implementations can share a
 * misreading of the standard.
 *
 * This decoder is written from the ISO/IEC 18004 specification's reading side, so
 * the test asserts the property the user cares about: the matrix, read back the
 * way a scanner reads it, yields exactly the payload. It deliberately shares no
 * code with [QrEncoder] - not the tables, not the placement, not the masking - so
 * a bug in one cannot hide behind the same bug in the other.
 *
 * Scope: level M, versions 1-10, byte mode, which is the whole range the encoder
 * emits. Anything else throws rather than returning a wrong string.
 */
object QrTestDecoder {

    /** Decode a matrix produced by [QrEncoder.encode]. */
    fun decode(matrix: Array<BooleanArray>): String {
        val size = matrix.size
        require(size >= 21 && (size - 17) % 4 == 0) { "not a QR dimension: $size" }
        val version = (size - 17) / 4
        require(version in QrEncoder.MIN_VERSION..QrEncoder.MAX_VERSION) {
            "unsupported version $version"
        }

        // ---- 1. the format information tells us the mask ----------------------
        val mask = readMask(matrix, size)

        // ---- 2. rebuild the reserved map, independently ------------------------
        // The decoder must know which modules it may read, and it derives that
        // from the geometry alone - exactly like a scanner that locates the
        // finders and timing strips.
        val reserved = reserveGeometry(size, version)

        // ---- 3. unmask, then read the zig-zag ---------------------------------
        val bits = StringBuilder()
        var col = size - 1
        var upward = true
        while (col > 0) {
            if (col == 6) col--
            for (step in 0 until size) {
                val row = if (upward) size - 1 - step else step
                for (dc in 0..1) {
                    val c = col - dc
                    if (reserved[row][c]) continue
                    var value = matrix[row][c]
                    if (isMasked(mask, row, c)) value = !value
                    bits.append(if (value) '1' else '0')
                }
            }
            upward = !upward
            col -= 2
        }

        // ---- 4. the block structure for this version and level ---------------
        val ecPerBlock = EC_PER_BLOCK[version - 1]
        val blockCount = BLOCK_COUNT[version - 1]
        val rawCodewords = TOTAL_CODEWORDS[version - 1]
        val totalDataCodewords = rawCodewords - ecPerBlock * blockCount

        // The interleave spreads data codewords across blocks, so read them back
        // into their blocks before the payload can be interpreted.
        val blockSizes = blockSizes(totalDataCodewords, blockCount)
        val dataBlocks = Array(blockCount) { IntArray(blockSizes[it]) }
        var cursor = 0
        val longest = blockSizes.max()
        for (index in 0 until longest) {
            for (block in 0 until blockCount) {
                if (index >= blockSizes[block]) continue
                dataBlocks[block][index] = readByte(bits, cursor)
                cursor += 8
            }
        }

        // ---- 5. read byte mode -------------------------------------------------
        val stream = dataBlocks.flatMap { it.toList() }
        var bitPos = 0
        fun readBits(count: Int): Int {
            var value = 0
            repeat(count) {
                val byte = stream[bitPos / 8]
                val bit = (byte shr (7 - bitPos % 8)) and 1
                value = (value shl 1) or bit
                bitPos++
            }
            return value
        }

        val mode = readBits(4)
        require(mode == 0b0100) { "not byte mode: $mode" }
        val lengthBits = if (version <= 9) 8 else 16
        val length = readBits(lengthBits)
        val payload = ByteArray(length) { readBits(8).toByte() }
        return String(payload, Charsets.UTF_8)
    }

    // -------------------------------------------------------------------------
    // Format information
    // -------------------------------------------------------------------------

    /**
     * Read the mask number from format copy 1, and verify it against copy 2.
     *
     * Checking BOTH is what makes a transposed format field fail: the two copies
     * are stored in different orientations on purpose, so an encoder that writes
     * one of them wrong produces two copies that disagree - which no scanner
     * tolerates and this decoder refuses.
     */
    private fun readMask(matrix: Array<BooleanArray>, size: Int): Int {
        // Copy 1, around the top-left finder: bits 0-5 down column 8, then bit 6
        // at (7,8), bit 7 in the corner, bit 8 at (8,7), then bits 9-14 LEFT along
        // row 8. (Row 6 and column 6 are the timing strips, which is why the run
        // skips them.)
        val copy1 = IntArray(15)
        for (i in 0..5) copy1[i] = if (matrix[i][8]) 1 else 0
        copy1[6] = if (matrix[7][8]) 1 else 0
        copy1[7] = if (matrix[8][8]) 1 else 0
        copy1[8] = if (matrix[8][7]) 1 else 0
        for (i in 9..14) copy1[i] = if (matrix[8][14 - i]) 1 else 0

        // Copy 2, split between the two other finders. Bit i sits at row 8 /
        // column size-1-i, and bit 14-i at column 8 / row size-1-i - the MIRROR of
        // copy 1, which is what lets a scanner work with either orientation.
        val copy2 = IntArray(15)
        for (i in 0..7) {
            copy2[i] = if (matrix[8][size - 1 - i]) 1 else 0
            copy2[14 - i] = if (matrix[size - 1 - i][8]) 1 else 0
        }

        require(copy1.contentEquals(copy2)) {
            "the two format-information copies disagree - the matrix is corrupt"
        }

        // Rebuild the 15-bit word MSB-first, undo the standard's 0x5412 XOR, then
        // take the low 3 bits (the 2 above them are the EC level).
        var format = 0
        for (i in 14 downTo 0) format = (format shl 1) or copy1[i]
        format = format xor 0x5412
        // bits 14..13 hold the EC level, 12..10 the mask.
        val ecLevel = (format shr 13) and 0b11
        require(ecLevel == 0b00) { "expected level M, read level $ecLevel" }
        return (format shr 10) and 0b111
    }

    // -------------------------------------------------------------------------
    // Geometry
    // -------------------------------------------------------------------------

    /** Every module the data does NOT occupy, derived from the symbol size only. */
    private fun reserveGeometry(size: Int, version: Int): Array<BooleanArray> {
        val reserved = Array(size) { BooleanArray(size) }

        // Finders plus their separators.
        fun finder(row: Int, col: Int) {
            for (dr in -1..7) {
                for (dc in -1..7) {
                    val r = row + dr
                    val c = col + dc
                    if (r in 0 until size && c in 0 until size) reserved[r][c] = true
                }
            }
        }
        finder(0, 0)
        finder(0, size - 7)
        finder(size - 7, 0)

        // Timing strips.
        for (i in 0 until size) {
            reserved[6][i] = true
            reserved[i][6] = true
        }

        // Alignment patterns.
        val centres = ALIGNMENT[version - 1]
        for (r in centres) {
            for (c in centres) {
                val overlaps = (r <= 8 && c <= 8) ||
                    (r <= 8 && c >= size - 9) ||
                    (r >= size - 9 && c <= 8)
                if (overlaps) continue
                for (dr in -2..2) {
                    for (dc in -2..2) reserved[r + dr][c + dc] = true
                }
            }
        }

        // Format areas plus the dark module.
        for (i in 0..8) {
            reserved[8][i] = true
            reserved[i][8] = true
        }
        for (i in 0 until 8) {
            reserved[8][size - 1 - i] = true
            reserved[size - 1 - i][8] = true
        }
        reserved[size - 8][8] = true

        // Version blocks, from version 7 up.
        if (version >= 7) {
            for (i in 0 until 18) {
                reserved[i / 3][size - 11 + i % 3] = true
                reserved[size - 11 + i % 3][i / 3] = true
            }
        }
        return reserved
    }

    private fun isMasked(mask: Int, row: Int, col: Int): Boolean = when (mask) {
        0 -> (row + col) % 2 == 0
        1 -> row % 2 == 0
        2 -> col % 3 == 0
        3 -> (row + col) % 3 == 0
        4 -> (row / 2 + col / 3) % 2 == 0
        5 -> (row * col) % 2 + (row * col) % 3 == 0
        6 -> ((row * col) % 2 + (row * col) % 3) % 2 == 0
        else -> ((row + col) % 2 + (row * col) % 3) % 2 == 0
    }

    /** Reads eight bits, MSB first, from the flat bit string. */
    private fun readByte(bits: StringBuilder, start: Int): Int {
        var value = 0
        for (i in start until start + 8) {
            value = (value shl 1) or if (bits[i] == '1') 1 else 0
        }
        return value
    }

    /**
     * The per-block data sizes for this version.
     *
     * The LAST blocks carry the extra byte when the total does not divide evenly -
     * the detail that makes versions 8-10 decode correctly and that is easy to get
     * backwards.
     */
    private fun blockSizes(totalData: Int, blocks: Int): IntArray {
        val base = totalData / blocks
        val extra = totalData % blocks
        // The first (blocks - extra) blocks are the SHORT ones.
        return IntArray(blocks) { index ->
            if (index < blocks - extra) base else base + 1
        }
    }

    // -------------------------------------------------------------------------
    // Tables (ISO/IEC 18004, level M)
    // -------------------------------------------------------------------------

    private val TOTAL_CODEWORDS = intArrayOf(
        26, 44, 70, 100, 134, 172, 196, 242, 292, 346,
    )
    private val EC_PER_BLOCK = intArrayOf(
        10, 16, 26, 18, 24, 16, 18, 22, 22, 26,
    )
    private val BLOCK_COUNT = intArrayOf(
        1, 1, 1, 2, 2, 4, 4, 4, 5, 5,
    )
    private val ALIGNMENT = arrayOf(
        intArrayOf(),
        intArrayOf(6, 18),
        intArrayOf(6, 22),
        intArrayOf(6, 26),
        intArrayOf(6, 30),
        intArrayOf(6, 34),
        intArrayOf(6, 22, 38),
        intArrayOf(6, 24, 42),
        intArrayOf(6, 26, 46),
        intArrayOf(6, 28, 50),
    )
}
